def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_mine = me[-1]
    last_opp = opp[-1]

    # Detect always-defect fast
    if n >= 4 and opp_d == n:
        return 'D'

    # Detect always-cooperate: cooperate, but exploit in late endgame
    if opp_d == 0:
        remaining = 100 - n
        if remaining <= 2:
            return 'D'
        if remaining <= 5 and n > 60:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    # Recent window analysis
    w = 10 if n >= 10 else n
    recent_opp = opp[-w:]
    recent_me = me[-w:]
    r_opp_c = recent_opp.count('C')
    r_opp_d = w - r_opp_c
    r_same = sum(1 for i in range(w) if recent_opp[i] == recent_me[i])
    r_opp_mirrors_me_prev = 0
    if n >= 2:
        start = n - w
        for i in range(start, n):
            if i >= 1 and opp[i] == me[i - 1]:
                r_opp_mirrors_me_prev += 1

    # Check if opponent mirrors our previous move strongly (TFT-like)
    if n >= 8 and r_opp_mirrors_me_prev >= (w - 1) * 0.85:
        # Exploit TFT: defect once, then cooperate to restore
        if last_mine == 'D' and last_opp == 'C':
            return 'C'
        if last_opp == 'C':
            # Occasionally defect to exploit
            if 5 < n < 95 and rng.random() < 0.15:
                return 'D'
            if n >= 95:
                return 'D'
        return 'C' if last_opp == 'C' else 'D'

    # Check opponent alternation
    if n >= 6:
        alt = 0
        for i in range(1, n):
            if opp[i] != opp[i - 1]:
                alt += 1
        if alt >= n - 2:
            # predictable alternator: play best response
            return 'D' if last_opp == 'C' else 'D'

    # Cooperative streak at end
    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    # Strong retaliation against sustained defection
    if streak_d >= 3:
        return 'D'

    # Endgame exploitation
    remaining = 100 - n
    if remaining <= 3:
        if opp_c > opp_d:
            return 'D'
        return 'D'
    if remaining <= 6 and n > 40:
        if opp_c >= n * 0.6:
            return 'D' if rng.random() < 0.7 else 'C'
        return 'D'

    # If opponent just defected on our cooperation: retaliate
    if last_mine == 'C' and last_opp == 'D':
        if opp_d > opp_c:
            return 'D'
        # Forgive single isolated defection
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'C'
        return 'D'

    # We just defected and opponent cooperated: probe/settle based on opp ratio
    if last_mine == 'D' and last_opp == 'C':
        # If opponent is very cooperative, keep cooperating to avoid collapse
        if opp_c >= opp_d + 3:
            return 'C'
        # Otherwise occasionally keep exploiting
        if n < 90 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Both cooperated: maybe probe occasionally
    if last_mine == 'C' and last_opp == 'C':
        if r_opp_mirrors_me_prev >= (w - 1) * 0.7 and n < 90:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    # Both defected: try to break the spiral if opponent seems otherwise cooperative
    if last_mine == 'D' and last_opp == 'D':
        if opp_c >= opp_d and r_opp_c >= 1:
            return 'C'
        return 'D'

    # Fallback: cooperate against cooperative, defect against exploitative
    if opp_c >= opp_d:
        return 'C'
    if rng.random() < 0.15:
        return 'C'
    return 'D'
